from pathlib import Path

root = Path(__file__).resolve().parents[1]
path = root / 'scripts' / 'equipment' / 'equipment-attachment.js'
text = path.read_text(encoding='utf-8')

old_position = """function getHavocHandCoverageLocalPosition(bone) {\n  if (!bone || typeof THREE === 'undefined' || !THREE.Vector3) return new THREE.Vector3(0, 0, 0);\n  if (!bone.children || typeof bone.getWorldPosition !== 'function' || typeof bone.worldToLocal !== 'function') {\n    return new THREE.Vector3(0, 0, 0);\n  }\n\n  const handWorld = new THREE.Vector3();\n  const fingerBasesWorld = new THREE.Vector3();\n  let fingerCount = 0;\n\n  bone.getWorldPosition(handWorld);\n\n  bone.children.forEach((child) => {\n    if (!child || !child.name || typeof child.getWorldPosition !== 'function') return;\n    const normalized = normalizeHavocBoneName(child.name);\n    if (!normalized.includes('hand')) return;\n    if (!/(thumb|index|middle|ring|pinky)/.test(normalized)) return;\n\n    const childWorld = new THREE.Vector3();\n    child.getWorldPosition(childWorld);\n    fingerBasesWorld.add(childWorld);\n    fingerCount += 1;\n  });\n\n  if (fingerCount === 0) return new THREE.Vector3(0, 0, 0);\n\n  fingerBasesWorld.multiplyScalar(1 / fingerCount);\n\n  /* Place the gauntlet root at the palm midpoint between wrist and finger bases. */\n  const palmWorld = handWorld.clone().lerp(fingerBasesWorld, 0.5);\n  return bone.worldToLocal(palmWorld);\n}\n"""

new_position = """function getHavocHandCoverageLocalPosition(bone) {\n  if (!bone || typeof THREE === 'undefined' || !THREE.Vector3) return new THREE.Vector3(0, 0, 0);\n  if (!bone.children || typeof bone.getWorldPosition !== 'function' || typeof bone.worldToLocal !== 'function') {\n    return new THREE.Vector3(0, 0, 0);\n  }\n\n  const handWorld = new THREE.Vector3();\n  const fingerBasesWorld = new THREE.Vector3();\n  let fingerCount = 0;\n\n  bone.getWorldPosition(handWorld);\n\n  bone.children.forEach((child) => {\n    if (!child || !child.name || typeof child.getWorldPosition !== 'function') return;\n    const normalized = normalizeHavocBoneName(child.name);\n    if (!normalized.includes('hand')) return;\n    if (!/(thumb|index|middle|ring|pinky)/.test(normalized)) return;\n\n    const childWorld = new THREE.Vector3();\n    child.getWorldPosition(childWorld);\n    fingerBasesWorld.add(childWorld);\n    fingerCount += 1;\n  });\n\n  if (fingerCount === 0) return new THREE.Vector3(0, 0, 0);\n\n  fingerBasesWorld.multiplyScalar(1 / fingerCount);\n\n  /* Keep the measured palm-center anchor. Hand-facing alignment is derived separately from finger spread. */\n  const palmWorld = handWorld.clone().lerp(fingerBasesWorld, 0.5);\n  return bone.worldToLocal(palmWorld);\n}\n"""

old_orient = """function orientHavocEquipmentAlongForearm(visualRoot, binding, bone) {\n  if (!visualRoot || !binding || !binding.baseVisualQuaternion || !bone || !bone.parent) return false;\n  if (typeof THREE === 'undefined' || !THREE.Vector3 || !THREE.Quaternion) return false;\n  if (typeof bone.getWorldPosition !== 'function' || typeof bone.parent.getWorldPosition !== 'function') return false;\n  if (typeof bone.getWorldQuaternion !== 'function') return false;\n\n  const handWorld = new THREE.Vector3();\n  const parentWorld = new THREE.Vector3();\n  const forearmDirectionWorld = new THREE.Vector3();\n  const forearmDirectionLocal = new THREE.Vector3();\n  const baseAxisLocal = new THREE.Vector3(0, 1, 0);\n  const boneWorldQuaternion = new THREE.Quaternion();\n  const inverseBoneWorldQuaternion = new THREE.Quaternion();\n  const alignmentQuaternion = new THREE.Quaternion();\n  const handRollQuaternion = new THREE.Quaternion();\n  const desiredQuaternion = new THREE.Quaternion();\n\n  bone.getWorldPosition(handWorld);\n  bone.parent.getWorldPosition(parentWorld);\n  forearmDirectionWorld.subVectors(handWorld, parentWorld);\n\n  if (forearmDirectionWorld.lengthSq() <= 1e-10) return false;\n  forearmDirectionWorld.normalize();\n\n  bone.getWorldQuaternion(boneWorldQuaternion);\n  inverseBoneWorldQuaternion.copy(boneWorldQuaternion).invert();\n  forearmDirectionLocal.copy(forearmDirectionWorld).applyQuaternion(inverseBoneWorldQuaternion).normalize();\n\n  baseAxisLocal.applyQuaternion(binding.baseVisualQuaternion).normalize();\n  alignmentQuaternion.setFromUnitVectors(baseAxisLocal, forearmDirectionLocal);\n\n  const rollAngle = HAVOC_EQUIPMENT_ATTACHMENT_CONFIG.activeHand === 'left'\n    ? Math.PI / 2\n    : -Math.PI / 2;\n  handRollQuaternion.setFromAxisAngle(new THREE.Vector3(0, 1, 0), rollAngle);\n  desiredQuaternion\n    .copy(alignmentQuaternion)\n    .multiply(binding.baseVisualQuaternion)\n    .multiply(handRollQuaternion)\n    .normalize();\n\n  visualRoot.quaternion.copy(desiredQuaternion);\n  return true;\n}\n"""

new_orient = """function orientHavocEquipmentAlongForearm(visualRoot, binding, bone) {\n  if (!visualRoot || !binding || !binding.baseVisualQuaternion || !bone || !bone.parent) return false;\n  if (typeof THREE === 'undefined' || !THREE.Vector3 || !THREE.Quaternion || !THREE.Matrix4) return false;\n  if (typeof bone.getWorldPosition !== 'function' || typeof bone.parent.getWorldPosition !== 'function') return false;\n  if (typeof bone.getWorldQuaternion !== 'function') return false;\n\n  const handWorld = new THREE.Vector3();\n  const parentWorld = new THREE.Vector3();\n  const indexWorld = new THREE.Vector3();\n  const pinkyWorld = new THREE.Vector3();\n  const forearmDirectionWorld = new THREE.Vector3();\n  const forearmDirectionLocal = new THREE.Vector3();\n  const palmWidthWorld = new THREE.Vector3();\n  const palmWidthLocal = new THREE.Vector3();\n  const palmNormalLocal = new THREE.Vector3();\n  const baseAxisLocal = new THREE.Vector3(0, 1, 0);\n  const baseWidthLocal = new THREE.Vector3(1, 0, 0);\n  const boneWorldQuaternion = new THREE.Quaternion();\n  const inverseBoneWorldQuaternion = new THREE.Quaternion();\n  const alignmentQuaternion = new THREE.Quaternion();\n  const desiredQuaternion = new THREE.Quaternion();\n  const rotationMatrix = new THREE.Matrix4();\n\n  bone.getWorldPosition(handWorld);\n  bone.parent.getWorldPosition(parentWorld);\n  forearmDirectionWorld.subVectors(handWorld, parentWorld);\n  if (forearmDirectionWorld.lengthSq() <= 1e-10) return false;\n  forearmDirectionWorld.normalize();\n\n  bone.getWorldQuaternion(boneWorldQuaternion);\n  inverseBoneWorldQuaternion.copy(boneWorldQuaternion).invert();\n  forearmDirectionLocal.copy(forearmDirectionWorld).applyQuaternion(inverseBoneWorldQuaternion).normalize();\n\n  let foundIndex = false;\n  let foundPinky = false;\n  bone.children.forEach((child) => {\n    if (!child || !child.name || typeof child.getWorldPosition !== 'function') return;\n    const normalized = normalizeHavocBoneName(child.name);\n    if (normalized.includes('index')) {\n      child.getWorldPosition(indexWorld);\n      foundIndex = true;\n    } else if (normalized.includes('pinky')) {\n      child.getWorldPosition(pinkyWorld);\n      foundPinky = true;\n    }\n  });\n\n  if (foundIndex && foundPinky) {\n    palmWidthWorld.subVectors(pinkyWorld, indexWorld);\n    if (palmWidthWorld.lengthSq() > 1e-10) {\n      palmWidthWorld.normalize();\n      palmWidthLocal.copy(palmWidthWorld).applyQuaternion(inverseBoneWorldQuaternion).normalize();\n      palmWidthLocal.addScaledVector(forearmDirectionLocal, -palmWidthLocal.dot(forearmDirectionLocal));\n      if (palmWidthLocal.lengthSq() > 1e-10) {\n        palmWidthLocal.normalize();\n        palmNormalLocal.crossVectors(palmWidthLocal, forearmDirectionLocal).normalize();\n        rotationMatrix.makeBasis(palmWidthLocal, forearmDirectionLocal, palmNormalLocal);\n        desiredQuaternion.setFromRotationMatrix(rotationMatrix).normalize();\n\n        /* Keep the authored hand side instead of introducing an arbitrary roll angle. */\n        baseWidthLocal.applyQuaternion(binding.baseVisualQuaternion).normalize();\n        if (baseWidthLocal.dot(palmWidthLocal) < 0) {\n          palmWidthLocal.negate();\n          palmNormalLocal.crossVectors(palmWidthLocal, forearmDirectionLocal).normalize();\n          rotationMatrix.makeBasis(palmWidthLocal, forearmDirectionLocal, palmNormalLocal);\n          desiredQuaternion.setFromRotationMatrix(rotationMatrix).normalize();\n        }\n\n        visualRoot.quaternion.copy(desiredQuaternion);\n        return true;\n      }\n    }\n  }\n\n  /* Safe fallback to the verified forearm alignment if finger spread is unavailable. */\n  baseAxisLocal.applyQuaternion(binding.baseVisualQuaternion).normalize();\n  alignmentQuaternion.setFromUnitVectors(baseAxisLocal, forearmDirectionLocal);\n  desiredQuaternion\n    .copy(alignmentQuaternion)\n    .multiply(binding.baseVisualQuaternion)\n    .normalize();\n  visualRoot.quaternion.copy(desiredQuaternion);\n  return true;\n}\n"""

if old_position not in text:
    raise SystemExit('Expected hand coverage function was not found. No changes made.')
if old_orient not in text:
    raise SystemExit('Expected orientation function was not found. No changes made.')

text = text.replace(old_position, new_position, 1)
text = text.replace(old_orient, new_orient, 1)

marker = "function prepareHavocEquipmentVisual(visualRoot) {"
texture = """function getHavocRustyIronMaterial() {\n  if (typeof THREE === 'undefined' || !THREE.MeshStandardMaterial) return null;\n  if (typeof globalThis !== 'undefined' && globalThis.__havocRustyIronMaterial) {\n    return globalThis.__havocRustyIronMaterial;\n  }\n  if (typeof document === 'undefined' || !THREE.CanvasTexture) return null;\n\n  const canvas = document.createElement('canvas');\n  canvas.width = 256;\n  canvas.height = 256;\n  const ctx = canvas.getContext('2d');\n  if (!ctx) return null;\n\n  ctx.fillStyle = '#3f403f';\n  ctx.fillRect(0, 0, 256, 256);\n  const image = ctx.getImageData(0, 0, 256, 256);\n  const data = image.data;\n  let seed = 0x6d2b79f5;\n  const rand = () => {\n    seed = (seed * 1664525 + 1013904223) >>> 0;\n    return seed / 4294967296;\n  };\n\n  for (let i = 0; i < data.length; i += 4) {\n    const iron = 48 + Math.floor(rand() * 42);\n    data[i] = iron;\n    data[i + 1] = iron;\n    data[i + 2] = iron - 2;\n    data[i + 3] = 255;\n  }\n  ctx.putImageData(image, 0, 0);\n\n  for (let i = 0; i < 950; i += 1) {\n    const x = rand() * 256;\n    const y = rand() * 256;\n    const r = 0.5 + rand() * 4.5;\n    const rust = rand();\n    ctx.fillStyle = rust > 0.55\n      ? `rgba(${105 + Math.floor(rand() * 55)},${45 + Math.floor(rand() * 35)},${20 + Math.floor(rand() * 20)},${0.12 + rand() * 0.35})`\n      : `rgba(15,15,15,${0.10 + rand() * 0.25})`;\n    ctx.beginPath();\n    ctx.arc(x, y, r, 0, Math.PI * 2);\n    ctx.fill();\n  }\n\n  ctx.strokeStyle = 'rgba(170,170,170,0.18)';\n  for (let i = 0; i < 90; i += 1) {\n    const x = rand() * 256;\n    const y = rand() * 256;\n    ctx.lineWidth = 0.4 + rand() * 1.2;\n    ctx.beginPath();\n    ctx.moveTo(x, y);\n    ctx.lineTo(x + 4 + rand() * 18, y + (rand() - 0.5) * 3);\n    ctx.stroke();\n  }\n\n  const texture = new THREE.CanvasTexture(canvas);\n  texture.wrapS = THREE.RepeatWrapping;\n  texture.wrapT = THREE.RepeatWrapping;\n  texture.repeat.set(1.2, 1.2);\n  texture.needsUpdate = true;\n\n  const material = new THREE.MeshStandardMaterial({\n    map: texture,\n    color: 0xffffff,\n    metalness: 0.72,\n    roughness: 0.58,\n  });\n  if (typeof globalThis !== 'undefined') globalThis.__havocRustyIronMaterial = material;\n  return material;\n}\n\n"""
if marker not in text:
    raise SystemExit('Material insertion marker was not found. No changes made.')
text = text.replace(marker, texture + marker, 1)

old_mesh = """      if (node.isMesh) {\n        node.frustumCulled = false;\n        node.visible = true;\n        if (node.geometry && typeof node.geometry.computeBoundingSphere === 'function') {\n          node.geometry.computeBoundingSphere();\n        }\n      }\n"""
new_mesh = """      if (node.isMesh) {\n        node.frustumCulled = false;\n        node.visible = true;\n        const rustyMaterial = getHavocRustyIronMaterial();\n        if (rustyMaterial) node.material = rustyMaterial;\n        if (node.geometry && typeof node.geometry.computeBoundingSphere === 'function') {\n          node.geometry.computeBoundingSphere();\n        }\n      }\n"""
if old_mesh not in text:
    raise SystemExit('Mesh preparation block was not found. No changes made.')
text = text.replace(old_mesh, new_mesh, 1)

path.write_text(text, encoding='utf-8')
print('Gauntlet appearance fix applied.')
